func (o *WorkspaceIssueCheck) SetApprovedByAccount(ctx context.Context, exec boil.ContextExecutor, insert bool, related *Account) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"workspace_issue_checks\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"approved_by_account_id"}),
		strmangle.WhereClause("\"", "\"", 2, workspaceIssueCheckPrimaryKeyColumns),
	)
	values := []any{related.ID, o.ID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.ApprovedByAccountID, related.ID)
	if o.R == nil {
		o.R = &workspaceIssueCheckR{
			ApprovedByAccount: related,
		}
	} else {
		o.R.ApprovedByAccount = related
	}

	if related.R == nil {
		related.R = &accountR{
			ApprovedByAccountWorkspaceIssueChecks: WorkspaceIssueCheckSlice{o},
		}
	} else {
		related.R.ApprovedByAccountWorkspaceIssueChecks = append(related.R.ApprovedByAccountWorkspaceIssueChecks, o)
	}

	return nil
}

